class EzCashCenterScreen extends ConsumerWidget {
 const EzCashCenterScreen({super.key,required this.profile});final EmployeeProfile profile;
 bool get owner=>profile.role==EmployeeRole.owner;
 @override Widget build(BuildContext context,WidgetRef ref)=>DefaultTabController(length:2,child:Scaffold(appBar:AppBar(title:const Text('EZ Cash Center'),bottom:const TabBar(tabs:[Tab(text:'Monthly Records'),Tab(text:'Reports & Exports')])),floatingActionButton:owner?FloatingActionButton.extended(onPressed:()=>_edit(context,ref),icon:const Icon(Icons.add),label:const Text('Add record')):null,body:TabBarView(children:[_EzCashRecordsTab(profile:profile),_EzCashReportsTab(profile:profile)])));
 Future<void> _edit(BuildContext context,WidgetRef ref,{EzCashRecord? record})async{
 final employees=await ref.read(businessCenterRepositoryProvider).employees();if(!context.mounted)return;if(employees.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('No active approved employees found.')));return;}
 String employeeId=record?.employeeId??employees.first['id'].toString();DateTime month=record?.periodMonth??DateTime(DateTime.now().year,DateTime.now().month,1);String status=record?.status??'pending';final amount=TextEditingController(text:record?.amount.toStringAsFixed(2)??'');final reference=TextEditingController(text:record?.reference??'');final last4=TextEditingController(text:record?.numberLast4??'');final note=TextEditingController(text:record?.ownerNote??'');
 final result=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,setD)=>AlertDialog(title:Text(record==null?'Add EZ Cash record':'Edit EZ Cash record'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[
 DropdownButtonFormField<String>(value:employeeId,decoration:const InputDecoration(labelText:'Employee'),items:employees.map((e)=>DropdownMenuItem(value:e['id'].toString(),child:Text('${e['name']} · ${e['agent_code']??''}'))).toList(),onChanged:record==null?(v)=>setD(()=>employeeId=v??employeeId):null),
 ListTile(title:const Text('Month'),subtitle:Text('${month.year}-${month.month.toString().padLeft(2,'0')}'),trailing:const Icon(Icons.calendar_month),onTap:()async{final d=await showDatePicker(context:ctx,initialDate:month,firstDate:DateTime(2020),lastDate:DateTime(2100),initialDatePickerMode:DatePickerMode.year);if(d!=null)setD(()=>month=DateTime(d.year,d.month,1));}),
 TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Amount (LKR)')),
 DropdownButtonFormField<String>(value:status,decoration:const InputDecoration(labelText:'Status'),items:const[DropdownMenuItem(value:'pending',child:Text('Pending')),DropdownMenuItem(value:'paid',child:Text('Paid')),DropdownMenuItem(value:'failed',child:Text('Failed')),DropdownMenuItem(value:'cancelled',child:Text('Cancelled'))],onChanged:(v)=>setD(()=>status=v??status)),
 TextField(controller:reference,decoration:const InputDecoration(labelText:'Payment reference (optional)')),
 TextField(controller:last4,maxLength:4,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Payment number — last 4 digits only')),
 TextField(controller:note,decoration:const InputDecoration(labelText:'Owner note'),maxLines:2),
 ])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Save'))]));
 if(result!=true)return;final value=double.tryParse(amount.text);if(value==null||!value.isFinite||value<0){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Enter a valid amount.')));return;}
 try{await ref.read(businessCenterRepositoryProvider).saveEzCashRecord(id:record?.id,employeeId:employeeId,teamId:employees.firstWhere((e)=>e['id'].toString()==employeeId)['team_id']?.toString(),month:month,amount:value,status:status,reference:reference.text,last4:last4.text.trim().isEmpty?null:last4.text,note:note.text,paidAt:status=='paid'?(record?.paidAt??DateTime.now()):null);ref.invalidate(ezCashRecordsProvider(null));if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('EZ Cash record saved.')));}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Save failed: $e')));}
 }
}

class _EzCashRecordsTab extends ConsumerStatefulWidget{const _EzCashRecordsTab({required this.profile});final EmployeeProfile profile;@override ConsumerState<_EzCashRecordsTab> createState()=>_EzCashRecordsTabState();}
class _EzCashRecordsTabState extends ConsumerState<_EzCashRecordsTab>{DateTime? month=DateTime(DateTime.now().year,DateTime.now().month,1);bool get owner=>widget.profile.role==EmployeeRole.owner;
 @override Widget build(BuildContext context)=>Column(children:[Padding(padding:const EdgeInsets.fromLTRB(12,8,12,0),child:Row(children:[const Expanded(child:Text('Filter month',style:TextStyle(fontWeight:FontWeight.bold))),TextButton.icon(onPressed:()async{final d=await showDatePicker(context:context,initialDate:month??DateTime.now(),firstDate:DateTime(2020),lastDate:DateTime(2100),initialDatePickerMode:DatePickerMode.year);if(d!=null)setState(()=>month=DateTime(d.year,d.month,1));},icon:const Icon(Icons.calendar_month),label:Text(month==null?'All months':'${month!.year}-${month!.month.toString().padLeft(2,'0')}')),IconButton(tooltip:'All months',onPressed:()=>setState(()=>month=null),icon:const Icon(Icons.filter_alt_off))])),Expanded(child:ref.watch(ezCashRecordsProvider(month)).when(data:(items){final total=items.fold<double>(0,(s,e)=>s+e.amount);return RefreshIndicator(onRefresh:()async=>ref.invalidate(ezCashRecordsProvider(month)),child:ListView(padding:const EdgeInsets.all(12),children:[Card(child:ListTile(title:const Text('Visible total'),subtitle:Text('${items.length} records'),trailing:Text('LKR ${total.toStringAsFixed(2)}',style:const TextStyle(fontWeight:FontWeight.bold)))),if(items.isEmpty)const Padding(padding:EdgeInsets.all(30),child:Text('No EZ Cash records for this period.',textAlign:TextAlign.center)),...items.map((r)=>Card(child:ListTile(leading:Icon(r.status=='paid'?Icons.check_circle:r.status=='failed'?Icons.error_outline:Icons.payments_outlined),title:Text(r.employeeName),subtitle:Text('${r.employeeCode} · ${r.periodMonth.year}-${r.periodMonth.month.toString().padLeft(2,'0')} · ${r.status.toUpperCase()}'),trailing:Text(r.amountLabel),onTap:()=>Navigator.push(context,MaterialPageRoute<void>(builder:(_)=>_EzCashDetails(record:r,profile:widget.profile)))))]));},loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('Could not load EZ Cash: $e'))))]);
}

class _EzCashDetails extends ConsumerWidget{const _EzCashDetails({required this.record,required this.profile});final EzCashRecord record;final EmployeeProfile profile;
 @override Widget build(BuildContext context,WidgetRef ref){final isOwner=profile.role==EmployeeRole.owner;return Scaffold(appBar:AppBar(title:const Text('EZ Cash Details'),actions:[if(isOwner)PopupMenuButton<String>(onSelected:(v)async{if(v=='delete'){final yes=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Delete record?'),content:const Text('This action is recorded in EZ Cash history.'),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Delete'))]));if(yes==true){try{await ref.read(businessCenterRepositoryProvider).deleteEzCashRecord(record.id);ref.invalidate(ezCashRecordsProvider(null));if(context.mounted)Navigator.pop(context);}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Delete failed: $e')));}}}},itemBuilder:(_)=>const[PopupMenuItem(value:'delete',child:Text('Delete record'))])]),body:ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(record.amountLabel,style:Theme.of(context).textTheme.headlineMedium),Text(record.employeeName),Text('Code: ${record.employeeCode}'),Text('Month: ${record.periodMonth.year}-${record.periodMonth.month.toString().padLeft(2,'0')}'),Text('Status: ${record.status}'),if(record.paidAt!=null)Text('Paid: ${record.paidAt}'),if(record.reference!=null)Text('Reference: ${record.reference}'),if(record.numberLast4!=null)Text('Payment number ending ${record.numberLast4}'),if(record.ownerNote!=null)Text('Owner note: ${record.ownerNote}')]))),const SizedBox(height:12),const Text('Change history',style:TextStyle(fontWeight:FontWeight.bold)),FutureBuilder<List<Map<String,dynamic>>>(future:ref.read(businessCenterRepositoryProvider).ezCashHistory(record.id),builder:(context,s)=>s.connectionState!=ConnectionState.done?const LinearProgressIndicator():s.hasError?Text('History unavailable: ${s.error}'):Column(children:(s.data??[]).map((h)=>ListTile(title:Text(h['event_type'].toString()),subtitle:Text(h['created_at'].toString()))).toList()))]));}
}

class _EzCashReportsTab extends ConsumerWidget{const _EzCashReportsTab({required this.profile});final EmployeeProfile profile;
 @override Widget build(BuildContext context,WidgetRef ref){final records=ref.watch(ezCashRecordsProvider(null));final reports=ref.watch(ezCashReportsProvider);final owner=profile.role==EmployeeRole.owner;return ListView(padding:const EdgeInsets.all(16),children:[const Text('Export current records',style:TextStyle(fontWeight:FontWeight.bold,fontSize:18)),const SizedBox(height:8),records.when(data:(items)=>Row(children:[Expanded(child:OutlinedButton.icon(onPressed:()=>_exportExcel(context,items),icon:const Icon(Icons.table_view),label:const Text('Excel'))),const SizedBox(width:10),Expanded(child:OutlinedButton.icon(onPressed:()=>_exportPdf(context,items),icon:const Icon(Icons.picture_as_pdf),label:const Text('PDF')))]),loading:()=>const LinearProgressIndicator(),error:(e,_)=>Text('Records unavailable: $e')),const Divider(height:32),Row(children:[const Expanded(child:Text('Uploaded reports',style:TextStyle(fontWeight:FontWeight.bold,fontSize:18))),if(owner)IconButton(onPressed:()=>_upload(context,ref),icon:const Icon(Icons.upload_file),tooltip:'Upload report')]),reports.when(data:(items)=>items.isEmpty?const Text('No uploaded EZ Cash reports.'):Column(children:items.map((r)=>ListTile(leading:Icon(r['mime_type']=='application/pdf'?Icons.picture_as_pdf:Icons.table_chart),title:Text(r['title'].toString()),subtitle:Text('${r['period_month']} · ${r['file_name']}'),trailing:IconButton(icon:const Icon(Icons.download),onPressed:()async{try{final url=await ref.read(businessCenterRepositoryProvider).ezCashReportUrl(r['file_path'].toString());if(!await launchUrl(Uri.parse(url),mode:LaunchMode.externalApplication))throw StateError('Could not open report');}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Download failed: $e')));}}))).toList()),loading:()=>const LinearProgressIndicator(),error:(e,_)=>Text('Reports unavailable: $e'))]);}
 Future<void> _upload(BuildContext context,WidgetRef ref)async{final title=TextEditingController();DateTime month=DateTime(DateTime.now().year,DateTime.now().month,1);final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,setD)=>AlertDialog(title:const Text('Upload EZ Cash report'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Title')),ListTile(title:const Text('Month'),subtitle:Text('${month.year}-${month.month.toString().padLeft(2,'0')}'),onTap:()async{final d=await showDatePicker(context:ctx,initialDate:month,firstDate:DateTime(2020),lastDate:DateTime(2100));if(d!=null)setD(()=>month=DateTime(d.year,d.month,1));})]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Choose file'))]));if(ok!=true)return;final f=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:const['pdf','xlsx','xls','csv'],withData:true);if(f==null||f.files.single.bytes==null)return;try{await ref.read(businessCenterRepositoryProvider).uploadEzCashReport(title:title.text,month:month,fileName:f.files.single.name,bytes:f.files.single.bytes!);ref.invalidate(ezCashReportsProvider);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Report uploaded.')));}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Upload failed: $e')));}}
 Future<void> _exportExcel(BuildContext context,List<EzCashRecord> records)async{final book=xl.Excel.createExcel();final sheet=book['EZ Cash'];sheet.appendRow(['Employee','Code','Month','Amount (LKR)','Status','Paid At','Reference'].map((v)=>xl.TextCellValue(v)).toList());for(final r in records){sheet.appendRow([xl.TextCellValue(r.employeeName),xl.TextCellValue(r.employeeCode),xl.TextCellValue('${r.periodMonth.year}-${r.periodMonth.month.toString().padLeft(2,'0')}'),xl.DoubleCellValue(r.amount),xl.TextCellValue(r.status),xl.TextCellValue(r.paidAt?.toIso8601String()??''),xl.TextCellValue(r.reference??'')]);}final bytes=book.encode();if(bytes==null)throw StateError('Excel export failed.');await SharePlus.instance.share(ShareParams(files:[XFile.fromData(Uint8List.fromList(bytes),mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',name:'ez_cash_report.xlsx')]));}
 Future<void> _exportPdf(BuildContext context,List<EzCashRecord> records)async{final doc=pw.Document();doc.addPage(pw.MultiPage(build:(_)=>[pw.Header(level:0,child:pw.Text('DD WORLD CONNECT — EZ Cash Report')),pw.Text('Generated: ${DateTime.now().toIso8601String()}'),pw.SizedBox(height:12),pw.Table(border:pw.TableBorder.all(),children:[pw.TableRow(children:['Employee','Code','Month','Amount LKR','Status'].map((v)=>pw.Padding(padding:const pw.EdgeInsets.all(4),child:pw.Text(v,style:pw.TextStyle(fontWeight:pw.FontWeight.bold,fontSize:8)))).toList()),...records.map((r)=>pw.TableRow(children:[r.employeeName,r.employeeCode,'${r.periodMonth.year}-${r.periodMonth.month.toString().padLeft(2,'0')}',r.amount.toStringAsFixed(2),r.status].map((v)=>pw.Padding(padding:const pw.EdgeInsets.all(4),child:pw.Text(v,style:const pw.TextStyle(fontSize:8)))).toList()))]) ]));final bytes=await doc.save();await SharePlus.instance.share(ShareParams(files:[XFile.fromData(bytes,mimeType:'application/pdf',name:'ez_cash_report.pdf')]));}
}
